{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Codeine, the closest structural analogue sharing the methoxy-morphinan core, has an absolute oral bioavailability of 80.5% in healthy subjects, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Samidorphan, a morphinan with a ketone and tertiary alcohol similar to the query, has an absolute oral bioavailability of 68.6% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Morphine, a closely related morphinan, reached 100% oral bioavailability in cirrhotic patients, demonstrating that this scaffold can achieve high systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Morphine in fasted healthy volunteers had a mean absolute oral bioavailability of 29.2%, above the 20% threshold, supporting high F albeit with a narrower margin.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a closely related morphinan, has an absolute oral bioavailability of 41% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Remoxipride, a CNS-active drug, has an absolute oral bioavailability of 92.6% in healthy subjects, supporting that this chemical space can have excellent oral bioavailability, though it is less structurally related.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is oxycodone, a morphinan opioid. The closest analogue codeine has F=80.5%; samidorphan, morphine, nalmefene, and remoxipride all show human F values ≥29%, with most >40%. No evidence supports F<20%, and the physicochemical prior is favorable. Therefore, the prediction is high oral bioavailability.",
  "evidence_gaps": [
    "No direct oxycodone absolute bioavailability measurement is included in the provided evidence; the prediction relies on close structural analogues.",
    "Some evidence comes from cirrhotic patients, where reduced first-pass metabolism may overestimate F relative to healthy individuals.",
    "Morphine fasted F=29.2% is close to the threshold, but still supports the high category."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

